SELECT bb.BOOKSET_ID as booksetId, #{HAPPEN_DATE} as happenDate, deal.FINPROD_ID as finprodId, finType.TYPE_18 AS secType, finType.TYPE_1 AS type1, deal.TRADE_MARKET AS tradeMarket, Q.INV_AIM AS invAim FROM BOK_BOOKSET bb INNER JOIN BOK_DEAL_ACCOUNTING acc ON acc.BOOKSET_ID = bb.BOOKSET_ID AND acc.HAPPEN_DATE = #{HAPPEN_DATE} INNER JOIN TRD_PRODUCT_DEAL deal ON deal.TRADE_ID = acc.BUSI_NO AND deal.PS = #{reclsPs} INNER JOIN FIN_PRODUCT_TYPE finType ON finType.FINPROD_ID = deal.FINPROD_ID AND finType.TYPE_18 IS NOT NULL INNER JOIN TRD_FIN_PRODUCT_BARTER Q ON Q.FINPROD_ID = deal.FINPROD_ID WHERE bb.bookset_type = #{booksetType} AND bb.START_DATE <= #{HAPPEN_DATE} AND bb.END_DATE >= #{HAPPEN_DATE}
AND (bb.BOOKSET_ID IN
null) OR bb.BOOKSET_ID in (
#{item}
)

SELECT bb.BOOKSET_ID as booksetId, #{HAPPEN_DATE} as happenDate, det.busi_id as finprodId, finType.TYPE_18 AS secType, finType.TYPE_1 AS type1, NVL(fin.TRADE_MARKET, trdFin.TRADE_MARKET) AS tradeMarket, bokDetailId.INV_AIM AS invAim FROM BOK_BOOKSET bb INNER JOIN BOK_STAT_DET_POSIITON det ON det.BOOKSET_ID = bb.BOOKSET_ID AND det.HAPPEN_DATE = #{HAPPEN_DATE} -1 INNER JOIN BOK_DETAIL_ID bokDetailId ON bokDetailId.BOOKSET_ID = bb.BOOKSET_ID AND bokDetailId.BOK_DETAIL_ID = det.BOK_DETAIL_ID INNER JOIN FIN_PRODUCT_TYPE finType ON finType.FINPROD_ID = det.BUSI_ID AND finType.TYPE_18 IS NOT NULL LEFT JOIN FIN_PRODUCT fin ON fin.FINPROD_ID = det.BUSI_ID LEFT JOIN FIN_TRADE_PRODUCT trdFin ON trdFin.FINPROD_ID = det.BUSI_ID WHERE bb.bookset_type = #{booksetType} AND bb.START_DATE <= #{HAPPEN_DATE} AND bb.END_DATE >= #{HAPPEN_DATE}
AND (bb.BOOKSET_ID IN
null) OR bb.BOOKSET_ID in (
#{item}
)
UNION
SELECT bb.BOOKSET_ID as booksetId, #{HAPPEN_DATE} as happenDate, deal.FINPROD_ID as finprodId, finType.TYPE_18 AS secType, finType.TYPE_1 AS type1, deal.TRADE_MARKET AS tradeMarket, deal.INV_AIM AS invAim FROM BOK_BOOKSET bb INNER JOIN BOK_DEAL_ACCOUNTING acc ON acc.BOOKSET_ID = bb.BOOKSET_ID AND acc.HAPPEN_DATE = #{HAPPEN_DATE} INNER JOIN TRD_PRODUCT_DEAL deal ON deal.TRADE_ID = acc.BUSI_NO INNER JOIN FIN_PRODUCT_TYPE finType ON finType.FINPROD_ID = deal.FINPROD_ID AND finType.TYPE_18 IS NOT NULL WHERE bb.bookset_type = #{booksetType} AND bb.START_DATE <= #{HAPPEN_DATE} AND bb.END_DATE >= #{HAPPEN_DATE} AND deal.PS != #{reclsPs} /** 去除重分类的交易 **/
AND (bb.BOOKSET_ID IN
null) OR bb.BOOKSET_ID in (
#{item}
)
